// ——— /canvas/<id> (le SSoT canvas.get → bloc éditorial) ——————————

describe('Canvas — /canvas/<id> (édition, le SSoT blocs TipTap)', () => {
  beforeEach(() => {
    cy.viewport(1280, 800);
    // Le stub de `canvas.get` (le Supabase PostgREST, le SSoT
    // 0022 RLS user_isolation) — un id fictif, jamais un id réel
    // (le spec ne suppose PAS l'existence d'une session courante).
    // Le SSoT column `blocks` (migration 0022, jsonb), PAS `blocks_json`.
    // La route RegExp de Cypress (le pattern le plus simple, le stub
    // REST supabase `canvas_sessions` — jamais un id réel).
    cy.intercept(
      'GET',
      /\/rest\/v1\/.*canvas_sessions/,
      {
        statusCode: 200,
        body: [
          {
            id: 'canvas-cy-test',
            user_id: 'uuid-user',
            title: 'Session Cypress',
            blocks: [{ id: 'b1', kind: 'md', content: '# Bonjour\n\nbloc markdown' }],
            artifact_id: null,
            locked: false,
            created_at: '2026-10-18T00:00:00Z',
            updated_at: '2026-10-18T00:00:00Z',
          },
        ],
      },
    ).as('canvasGet');
    // Les commentaires (le SSoT canvas.listComments, le même stub REST
    // `canvas_comments`).
    cy.intercept('GET', /\/rest\/v1\/.*canvas_comments/, {
      statusCode: 200,
      body: [],
    }).as('canvasComments');

    cy.visit('/canvas/canvas-cy-test', { timeout: 180000 });
    cy.wait('@canvasGet');
  });

  it('affiche le bloc éditorial (le SSoT data-canvas-block, le TipTap StarterKit)', () => {
    cy.get('[data-canvas-block="b1"]').should('exist');
    cy.get('[data-canvas-block="b1"]').should('contain.text', 'Bonjour');
    cy.screenshot('03-canvas-block-editor');
  });
});

